void SEffTextureAndMirror::Use( CRenderContext *p )
{
	CVec4 vParams( 0, 0, fDielMirror, fMetalMirror );
	p->SetPixelShader( psTextureAndMirror );
	p->SetVertexShader( vsTextureAndMirror );
	p->SetVSConst( 14, vParams );
	p->SetTexture( 0, pTex );
	p->SetTexture( 1, pTexMirror );
}
